INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'array-basics', 'Array Fundamentals', 'Understand how arrays work under the hood and master fundamental operations', 'An array is a contiguous block of memory that stores elements of the same data type. Each element is identified by an index, starting from 0 in most languages.

Memory Layout:
Arrays allocate a fixed block of memory. If you create int[] arr = new int[5], the JVM allocates 5 × 4 = 20 bytes of contiguous memory. This is why random access is O(1) — the address of any element can be calculated as:
  address = baseAddress + (index × elementSize)

Types of Arrays:
- **Static Arrays**: Fixed size, allocated at compile time (e.g., int[] in Java)
- **Dynamic Arrays**: Resize automatically (e.g., ArrayList in Java, vector in C++)
- **Multi-dimensional Arrays**: Arrays of arrays (e.g., int[][] for matrices)

Time Complexities:
- Access by index: O(1)
- Search (unsorted): O(n)
- Search (sorted): O(log n) with binary search
- Insertion at end: O(1) amortized for dynamic arrays
- Insertion at beginning/middle: O(n) due to shifting
- Deletion: O(n) due to shifting

Dynamic Array Resizing:
When an ArrayList reaches capacity, it creates a new array (typically 1.5× or 2× the size) and copies all elements. This is why insertion is O(1) *amortized* — most insertions are O(1), but occasionally one is O(n).', 'Arrays are the backbone of nearly every application. Database indexes use arrays for fast lookups. Image processing treats pixels as 2D arrays. Game engines use arrays for entity management. Even hash tables use arrays internally.', '["ArrayIndexOutOfBoundsException — accessing index >= length or < 0","Confusing array length with last valid index (last index = length - 1)","Not initializing arrays (default values: 0 for int, null for objects, false for boolean)","Using == to compare arrays instead of Arrays.equals()","Forgetting that arrays are passed by reference, not by value"]', '["Always check bounds before accessing: if (i >= 0 && i < arr.length)","Use Arrays.sort(), Arrays.fill(), Arrays.copyOf() utility methods","Prefer ArrayList when size is unknown at compile time","Use enhanced for-loop (for-each) when you don''t need the index","Initialize with meaningful sizes to avoid unnecessary resizing"]', 'Array fundamentals are tested in every coding interview. You must know time complexities cold and understand when to use static vs dynamic arrays.', '12 min', 'java', '// Array Declaration & Initialization
int[] nums = new int[5];             // [0, 0, 0, 0, 0]
int[] primes = {2, 3, 5, 7, 11};    // Literal initialization
String[] names = new String[3];      // [null, null, null]

// Basic Operations
nums[0] = 10;                        // O(1) - Set element
int val = primes[2];                 // O(1) - Get element (val = 5)
int len = primes.length;             // O(1) - Get length

// Traversal
for (int i = 0; i < nums.length; i++) {
    System.out.println(nums[i]);     // Index-based traversal
}
for (int num : primes) {
    System.out.println(num);         // Enhanced for-loop
}

// Utility Methods
Arrays.sort(nums);                   // O(n log n) - Sort in-place
Arrays.fill(nums, -1);              // O(n) - Fill with value
int[] copy = Arrays.copyOf(primes, primes.length); // O(n)
int idx = Arrays.binarySearch(primes, 7); // O(log n) - must be sorted

// Dynamic Array (ArrayList)
ArrayList<Integer> list = new ArrayList<>();
list.add(10);          // O(1) amortized - Add to end
list.add(0, 5);        // O(n) - Insert at index 0
list.get(0);           // O(1) - Access by index
list.remove(0);        // O(n) - Remove at index
list.size();           // O(1) - Get size
list.contains(10);     // O(n) - Search', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'dsa' AND s.slug = 'arrays-strings';
INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'array-operations', 'Common Array Operations', 'Master essential array manipulation patterns: reversal, rotation, partitioning, and merging', 'Beyond basic access and traversal, several array operations form the building blocks of more complex algorithms.

1. Reversal:
Swap elements from both ends moving inward. Uses two pointers — one at start, one at end.
Time: O(n), Space: O(1)

2. Rotation:
Shift elements left or right by k positions. The trick: three reversals.
- Left rotate by k: Reverse first k → Reverse remaining → Reverse all
Time: O(n), Space: O(1)

3. Partitioning:
Rearrange elements around a pivot (used in QuickSort). Dutch National Flag variant handles three-way partition.

4. Merging Sorted Arrays:
Use two pointers, one for each array. Compare and pick the smaller element.
Time: O(n + m), Space: O(n + m)

5. Removing Duplicates (Sorted Array):
Use a slow pointer to track the position of the next unique element while the fast pointer scans ahead.
Time: O(n), Space: O(1)

6. Finding Max Subarray (Kadane''s preview):
Track current sum and reset when it goes negative.', 'Array rotation is used in circular buffers and job scheduling. Partitioning is fundamental to QuickSort (one of the fastest sorting algorithms). Merging sorted arrays powers merge sort and database join operations.', '["Not handling k > array.length in rotation (use k % length)","Creating a new array when in-place modification is possible","Off-by-one errors in the reversal swap loop","Forgetting to handle empty arrays or single-element arrays","Using nested loops (O(n²)) when a two-pointer approach gives O(n)"]', '["Master the reverse-based rotation trick — it appears in many problems","Always consider in-place solutions first to minimize space usage","Use the two-pointer technique for sorted array problems","Test with edge cases: empty array, single element, all duplicates","Draw out small examples before coding to verify your logic"]', 'Array manipulation problems are the most common interview questions at FAANG companies. Problems like ''Rotate Array'', ''Move Zeroes'', ''Remove Duplicates'' are frequently asked in phone screens.', '15 min', 'java', '// 1. Reverse an Array In-Place
public void reverse(int[] arr, int left, int right) {
    while (left < right) {
        int temp = arr[left];
        arr[left++] = arr[right];
        arr[right--] = temp;
    }
}

// 2. Rotate Array Left by K positions (Three Reversal Trick)
// [1,2,3,4,5] rotate left by 2 → [3,4,5,1,2]
public void rotateLeft(int[] arr, int k) {
    int n = arr.length;
    k = k % n;                    // Handle k > n
    reverse(arr, 0, k - 1);      // Reverse first k: [2,1,3,4,5]
    reverse(arr, k, n - 1);      // Reverse rest:    [2,1,5,4,3]
    reverse(arr, 0, n - 1);      // Reverse all:     [3,4,5,1,2]
}

// 3. Remove Duplicates from Sorted Array (In-Place)
// [1,1,2,2,3] → [1,2,3,_,_] returns 3
public int removeDuplicates(int[] nums) {
    if (nums.length == 0) return 0;
    int slow = 0;
    for (int fast = 1; fast < nums.length; fast++) {
        if (nums[fast] != nums[slow]) {
            nums[++slow] = nums[fast];
        }
    }
    return slow + 1;
}

// 4. Move Zeroes to End (Maintain Order)
// [0,1,0,3,12] → [1,3,12,0,0]
public void moveZeroes(int[] nums) {
    int insertPos = 0;
    for (int num : nums) {
        if (num != 0) nums[insertPos++] = num;
    }
    while (insertPos < nums.length) {
        nums[insertPos++] = 0;
    }
}

// 5. Merge Two Sorted Arrays
public int[] merge(int[] a, int[] b) {
    int[] result = new int[a.length + b.length];
    int i = 0, j = 0, k = 0;
    while (i < a.length && j < b.length) {
        result[k++] = (a[i] <= b[j]) ? a[i++] : b[j++];
    }
    while (i < a.length) result[k++] = a[i++];
    while (j < b.length) result[k++] = b[j++];
    return result;
}', 1 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'dsa' AND s.slug = 'arrays-strings';
INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'string-basics', 'String Manipulation', 'Master string operations, immutability, and common manipulation patterns', 'Strings in Java are immutable sequences of characters backed by a char[] (or byte[] since Java 9). Once created, a String object cannot be modified — any "modification" creates a new String.

String Pool:
Java maintains a String Pool (intern pool) in heap memory. String literals are automatically interned:
  String a = "hello";  // Goes to pool
  String b = "hello";  // Reuses same object from pool
  String c = new String("hello"); // Creates new object on heap
  a == b    // true (same reference)
  a == c    // false (different references)
  a.equals(c) // true (same content)

Key String Methods:
- charAt(i) — O(1) character access
- substring(start, end) — O(n) creates new string
- indexOf(str) — O(n×m) naive search
- split(regex) — O(n) tokenization
- trim() / strip() — remove whitespace
- toCharArray() — O(n) convert to char[]

StringBuilder vs String:
String concatenation in a loop creates n intermediate objects → O(n²).
StringBuilder maintains a mutable char buffer → O(n).

Character Classification:
Character.isLetter(), isDigit(), isWhitespace(), toLowerCase(), toUpperCase() are essential for parsing problems.', 'String manipulation powers search engines, text editors, compilers, data validation (email, URL parsing), encryption algorithms, and natural language processing pipelines.', '["Using == instead of .equals() to compare string content","Concatenating strings in a loop with + instead of StringBuilder","Not handling null strings (NullPointerException)","Forgetting that substring() creates a new String (memory consideration)","Ignoring Unicode — some characters are multi-byte (emoji, CJK)"]', '["Always use .equals() or Objects.equals() for string comparison","Use StringBuilder for any loop-based string building","Convert to char[] for in-place manipulation problems","Use String.valueOf() instead of concatenation for type conversion","Consider case sensitivity — use equalsIgnoreCase() or toLowerCase()"]', 'String problems are ubiquitous in interviews: reverse strings, check palindromes, find anagrams, implement strStr(). Understanding immutability and StringBuilder is fundamental.', '12 min', 'java', '// 1. Reverse a String
public String reverse(String s) {
    return new StringBuilder(s).reverse().toString();
}

// 2. Check Palindrome
public boolean isPalindrome(String s) {
    s = s.toLowerCase().replaceAll("[^a-z0-9]", "");
    int left = 0, right = s.length() - 1;
    while (left < right) {
        if (s.charAt(left++) != s.charAt(right--)) return false;
    }
    return true;
}

// 3. Check if Two Strings are Anagrams
public boolean isAnagram(String s, String t) {
    if (s.length() != t.length()) return false;
    int[] count = new int[26];
    for (int i = 0; i < s.length(); i++) {
        count[s.charAt(i) - ''a'']++;
        count[t.charAt(i) - ''a'']--;
    }
    for (int c : count) {
        if (c != 0) return false;
    }
    return true;
}

// 4. StringBuilder for Efficient Concatenation
public String buildString(String[] words) {
    StringBuilder sb = new StringBuilder();
    for (String word : words) {
        sb.append(word).append(" ");
    }
    return sb.toString().trim();
}

// 5. Count Character Frequency
public Map<Character, Integer> charFrequency(String s) {
    Map<Character, Integer> freq = new HashMap<>();
    for (char c : s.toCharArray()) {
        freq.merge(c, 1, Integer::sum);
    }
    return freq;
}

// 6. First Non-Repeating Character
public int firstUniqChar(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) count[c - ''a'']++;
    for (int i = 0; i < s.length(); i++) {
        if (count[s.charAt(i) - ''a''] == 1) return i;
    }
    return -1;
}', 2 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'dsa' AND s.slug = 'arrays-strings';
INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'two-pointers', 'Two Pointers Technique', 'Learn the two-pointer pattern to solve array and string problems in O(n) time', 'The Two Pointers technique uses two indices that move through an array or string to solve problems efficiently, typically reducing O(n²) brute force to O(n).

Three Main Patterns:

1. Opposite Direction (Converging):
Start one pointer at the beginning, one at the end. Move them toward each other.
Use cases: Pair sum in sorted array, palindrome check, container with most water.

2. Same Direction (Fast & Slow):
Both pointers start at the beginning. The fast pointer moves ahead while the slow pointer tracks a condition.
Use cases: Remove duplicates, move zeroes, remove element, linked list cycle detection.

3. Two Arrays:
One pointer per array, advancing based on comparison.
Use cases: Merge sorted arrays, intersection of arrays.

When to Use Two Pointers:
- The array is sorted (or sorting is acceptable)
- You need to find a pair/triplet that satisfies a condition
- You need to partition or rearrange elements in-place
- You need O(1) extra space

Key Insight: Two pointers work because the sorted order (or some invariant) guarantees that you don''t miss any valid pair by skipping elements.', 'Two pointers optimize search algorithms in databases, power merge operations in distributed systems, and enable efficient text matching in editors. The pattern appears in network packet merging and memory defragmentation.', '["Forgetting to sort the array first when the technique requires sorted order","Infinite loops — ensure at least one pointer moves each iteration","Not handling duplicates (e.g., 3Sum requires skipping duplicate values)","Using two pointers when the array isn''t sorted and sorting would lose index info","Off-by-one: using <= vs < in the while condition"]', '["Draw out the pointer movements on paper before coding","Clearly define what each pointer represents (slow = insertion point, fast = scanner)","Always handle edge cases: empty array, single element, all same elements","For 3Sum/4Sum, reduce to 2Sum with an outer loop","Use while (left < right) for converging, while (fast < n) for same-direction"]', 'Two pointers is one of the top 3 most important patterns. Problems: Two Sum II, 3Sum, Container With Most Water, Trapping Rain Water, Remove Duplicates — all FAANG favorites.', '18 min', 'java', '// 1. Two Sum II (Sorted Array) — Converging Pointers
public int[] twoSumSorted(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left < right) {
        int sum = nums[left] + nums[right];
        if (sum == target) return new int[]{left, right};
        else if (sum < target) left++;
        else right--;
    }
    return new int[]{};
}

// 2. Three Sum — Sort + Two Pointers
public List<List<Integer>> threeSum(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> result = new ArrayList<>();
    for (int i = 0; i < nums.length - 2; i++) {
        if (i > 0 && nums[i] == nums[i-1]) continue; // skip dupes
        int left = i + 1, right = nums.length - 1;
        while (left < right) {
            int sum = nums[i] + nums[left] + nums[right];
            if (sum == 0) {
                result.add(Arrays.asList(nums[i], nums[left], nums[right]));
                while (left < right && nums[left] == nums[left+1]) left++;
                while (left < right && nums[right] == nums[right-1]) right--;
                left++; right--;
            } else if (sum < 0) left++;
            else right--;
        }
    }
    return result;
}

// 3. Container With Most Water — Converging Pointers
public int maxArea(int[] height) {
    int left = 0, right = height.length - 1, max = 0;
    while (left < right) {
        int area = Math.min(height[left], height[right]) * (right - left);
        max = Math.max(max, area);
        if (height[left] < height[right]) left++;
        else right--;
    }
    return max;
}

// 4. Remove Element In-Place — Same Direction
public int removeElement(int[] nums, int val) {
    int slow = 0;
    for (int fast = 0; fast < nums.length; fast++) {
        if (nums[fast] != val) {
            nums[slow++] = nums[fast];
        }
    }
    return slow;
}', 3 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'dsa' AND s.slug = 'arrays-strings';
INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'sliding-window', 'Sliding Window Pattern', 'Master the sliding window technique for subarray and substring problems', 'The Sliding Window pattern maintains a "window" (contiguous subarray/substring) that expands and shrinks to find optimal solutions. It converts O(n²) or O(n³) brute force into O(n).

Two Types:

1. Fixed-Size Window:
Window size k is given. Slide the window one element at a time, adding the new element and removing the old.
Use cases: Max sum subarray of size k, moving average.

2. Variable-Size Window (Expand/Shrink):
Expand the right pointer to include more elements. When a condition is violated, shrink from the left.
Use cases: Longest substring without repeating chars, minimum window substring, longest subarray with sum ≤ k.

Template for Variable Window:
  left = 0
  for right in range(n):
      // Add arr[right] to window state
      while (window is invalid):
          // Remove arr[left] from window state
          left++
      // Update answer with current window

Key Insight: The window only moves forward — left never goes backward. This ensures each element is processed at most twice (once added, once removed), giving O(n) total.

Common State Tracking:
- HashMap for character/element frequency
- Running sum for numeric windows
- Set for uniqueness checks
- Counter for condition tracking', 'Sliding windows power real-time analytics (moving averages in stock prices), network congestion control (TCP window), streaming data processing, and rate limiting algorithms.', '["Shrinking the window too aggressively — only shrink when the condition is violated","Forgetting to update the window state when removing the left element","Not handling the case where no valid window exists","Using a fixed-size approach for a variable-size problem (or vice versa)","Off-by-one in window size calculation: size = right - left + 1"]', '["Identify whether the window is fixed or variable first","Use a HashMap to track character frequencies in substring problems","Update your answer inside the valid window section, not inside the shrink loop","For ''minimum'' problems, update answer when window is valid; for ''maximum'', update before/after shrinking","Always verify with examples: does left advance correctly?"]', 'Sliding window is a top-tier interview pattern. Must-know problems: Longest Substring Without Repeating Characters (Medium), Minimum Window Substring (Hard), Maximum Sum Subarray of Size K.', '20 min', 'java', '// 1. Maximum Sum Subarray of Size K (Fixed Window)
public int maxSumSubarray(int[] arr, int k) {
    int windowSum = 0, maxSum = Integer.MIN_VALUE;
    for (int i = 0; i < arr.length; i++) {
        windowSum += arr[i];
        if (i >= k - 1) {
            maxSum = Math.max(maxSum, windowSum);
            windowSum -= arr[i - k + 1]; // Remove leftmost
        }
    }
    return maxSum;
}

// 2. Longest Substring Without Repeating Characters (Variable)
public int lengthOfLongestSubstring(String s) {
    Map<Character, Integer> lastSeen = new HashMap<>();
    int maxLen = 0, left = 0;
    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        if (lastSeen.containsKey(c) && lastSeen.get(c) >= left) {
            left = lastSeen.get(c) + 1;
        }
        lastSeen.put(c, right);
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}

// 3. Minimum Window Substring
public String minWindow(String s, String t) {
    Map<Character, Integer> need = new HashMap<>();
    for (char c : t.toCharArray()) need.merge(c, 1, Integer::sum);
    
    int left = 0, matched = 0, minLen = Integer.MAX_VALUE, start = 0;
    Map<Character, Integer> window = new HashMap<>();
    
    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        window.merge(c, 1, Integer::sum);
        if (need.containsKey(c) && window.get(c).equals(need.get(c)))
            matched++;
        
        while (matched == need.size()) {
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                start = left;
            }
            char leftChar = s.charAt(left++);
            if (need.containsKey(leftChar) && window.get(leftChar).equals(need.get(leftChar)))
                matched--;
            window.merge(leftChar, -1, Integer::sum);
        }
    }
    return minLen == Integer.MAX_VALUE ? "" : s.substring(start, start + minLen);
}', 4 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'dsa' AND s.slug = 'arrays-strings';
INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'prefix-sum', 'Prefix Sum Arrays', 'Use prefix sums to answer range queries in O(1) time after O(n) preprocessing', 'A Prefix Sum array stores cumulative sums: prefix[i] = sum of elements from index 0 to i.

Construction: O(n)
  prefix[0] = arr[0]
  prefix[i] = prefix[i-1] + arr[i]

Range Sum Query: O(1)
  sum(l, r) = prefix[r] - prefix[l-1]
  (Use prefix[r] if l == 0)

This converts repeated O(n) range sum queries into O(1) lookups after one O(n) preprocessing step.

Variations:
1. Prefix Sum with HashMap:
   For "subarray with sum = k", store prefix sums in a HashMap. If prefix[j] - prefix[i] = k, then subarray (i+1, j) sums to k.

2. 2D Prefix Sum:
   For matrix region sum queries. Build a 2D prefix matrix where each cell contains the sum of the rectangle from (0,0) to (i,j).

3. Difference Array:
   The inverse of prefix sum. Used for range update operations: to add val to all elements in range [l, r], set diff[l] += val and diff[r+1] -= val, then compute prefix sum.

When to Use:
- Multiple range sum queries on a static array
- Finding subarrays with a target sum
- Counting subarrays satisfying sum conditions
- 2D region sum queries', 'Prefix sums power database aggregate queries, image processing (integral images for fast blur/feature detection), financial running totals, and network traffic analysis over time windows.', '["Off-by-one: forgetting to handle l == 0 case in range sum","Modifying the original array after building the prefix sum (invalidates it)","Integer overflow for large arrays — use long instead of int","Confusing 0-indexed and 1-indexed prefix arrays","Not recognizing that ''subarray sum equals k'' is a prefix sum + HashMap problem"]', '["Use 1-indexed prefix arrays to avoid special-casing l == 0","Use long[] for prefix sums to prevent overflow","Combine with HashMap for subarray sum problems","For 2D, use inclusion-exclusion: sum(r1,c1,r2,c2) = P[r2][c2] - P[r1-1][c2] - P[r2][c1-1] + P[r1-1][c1-1]","Consider difference arrays when you need range updates instead of range queries"]', 'Prefix sum is essential for medium/hard interview problems. Key problems: Subarray Sum Equals K, Contiguous Array, Range Sum Query 2D, Product of Array Except Self.', '15 min', 'java', '// 1. Build Prefix Sum Array
public int[] buildPrefixSum(int[] arr) {
    int[] prefix = new int[arr.length];
    prefix[0] = arr[0];
    for (int i = 1; i < arr.length; i++) {
        prefix[i] = prefix[i-1] + arr[i];
    }
    return prefix;
}

// Range Sum Query: sum of arr[l..r]
public int rangeSum(int[] prefix, int l, int r) {
    return l == 0 ? prefix[r] : prefix[r] - prefix[l-1];
}

// 2. Subarray Sum Equals K (Prefix Sum + HashMap)
public int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> prefixCount = new HashMap<>();
    prefixCount.put(0, 1); // Base case: empty prefix
    int sum = 0, count = 0;
    for (int num : nums) {
        sum += num;
        // If (sum - k) was a previous prefix sum,
        // then subarray between them sums to k
        count += prefixCount.getOrDefault(sum - k, 0);
        prefixCount.merge(sum, 1, Integer::sum);
    }
    return count;
}

// 3. Product of Array Except Self (Prefix + Suffix Products)
public int[] productExceptSelf(int[] nums) {
    int n = nums.length;
    int[] result = new int[n];
    
    // Forward pass: prefix products
    result[0] = 1;
    for (int i = 1; i < n; i++) {
        result[i] = result[i-1] * nums[i-1];
    }
    // Backward pass: multiply by suffix products
    int suffix = 1;
    for (int i = n - 1; i >= 0; i--) {
        result[i] *= suffix;
        suffix *= nums[i];
    }
    return result;
}

// 4. Contiguous Array (Longest Subarray with Equal 0s and 1s)
public int findMaxLength(int[] nums) {
    Map<Integer, Integer> firstSeen = new HashMap<>();
    firstSeen.put(0, -1);
    int sum = 0, maxLen = 0;
    for (int i = 0; i < nums.length; i++) {
        sum += (nums[i] == 0) ? -1 : 1;
        if (firstSeen.containsKey(sum)) {
            maxLen = Math.max(maxLen, i - firstSeen.get(sum));
        } else {
            firstSeen.put(sum, i);
        }
    }
    return maxLen;
}', 5 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'dsa' AND s.slug = 'arrays-strings';
INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'kadanes-algorithm', 'Kadane''s Algorithm', 'Find the maximum sum subarray in O(n) time using dynamic programming', 'Kadane''s Algorithm finds the contiguous subarray with the maximum sum in O(n) time and O(1) space. It''s a classic example of dynamic programming.

Core Idea:
At each index i, decide: should I extend the previous subarray or start a new one here?
  currentMax = max(arr[i], currentMax + arr[i])
  globalMax = max(globalMax, currentMax)

If currentMax + arr[i] < arr[i], that means the previous subarray had a negative sum — it''s better to start fresh.

Step-by-step for [-2, 1, -3, 4, -1, 2, 1, -5, 4]:
  i=0: current=-2, global=-2
  i=1: current=max(1, -2+1)=1, global=1
  i=2: current=max(-3, 1-3)=-2, global=1
  i=3: current=max(4, -2+4)=4, global=4
  i=4: current=max(-1, 4-1)=3, global=4
  i=5: current=max(2, 3+2)=5, global=5
  i=6: current=max(1, 5+1)=6, global=6 ✓
  i=7: current=max(-5, 6-5)=1, global=6
  i=8: current=max(4, 1+4)=5, global=6
  Answer: 6 (subarray [4, -1, 2, 1])

Variations:
- Track start/end indices of the max subarray
- Maximum circular subarray sum
- Maximum product subarray (track both max and min)
- Maximum sum with at most k elements', 'Kadane''s algorithm is used in financial analysis (maximum profit period), signal processing (strongest signal segment), bioinformatics (gene sequence analysis), and image processing (maximum brightness region).', '["Not handling all-negative arrays (initialize globalMax to arr[0], not 0)","Forgetting to reset currentMax when it goes below the current element","Confusing maximum subarray sum with maximum subsequence sum (subsequence doesn''t need contiguity)","Not tracking indices when the problem asks for the actual subarray","Applying Kadane''s to circular arrays without the min-subarray trick"]', '["Initialize both currentMax and globalMax to arr[0], not 0 or Integer.MIN_VALUE","For the circular variant: answer = max(normalKadane, totalSum - minSubarraySum)","For max product: track both maxProduct and minProduct (negative × negative = positive)","Always verify with all-negative input: [-3, -1, -2] should return -1","This is DP where dp[i] = max(arr[i], dp[i-1] + arr[i]), optimized to O(1) space"]', 'Kadane''s Algorithm is a FAANG classic. It tests DP intuition and greedy thinking. Variants like Maximum Product Subarray and Maximum Circular Subarray Sum are common follow-ups.', '12 min', 'java', '// 1. Classic Kadane''s Algorithm
public int maxSubArray(int[] nums) {
    int currentMax = nums[0];
    int globalMax = nums[0];
    for (int i = 1; i < nums.length; i++) {
        currentMax = Math.max(nums[i], currentMax + nums[i]);
        globalMax = Math.max(globalMax, currentMax);
    }
    return globalMax;
}

// 2. Kadane''s with Subarray Indices
public int[] maxSubArrayWithIndices(int[] nums) {
    int currentMax = nums[0], globalMax = nums[0];
    int start = 0, end = 0, tempStart = 0;
    for (int i = 1; i < nums.length; i++) {
        if (nums[i] > currentMax + nums[i]) {
            currentMax = nums[i];
            tempStart = i;
        } else {
            currentMax += nums[i];
        }
        if (currentMax > globalMax) {
            globalMax = currentMax;
            start = tempStart;
            end = i;
        }
    }
    return new int[]{globalMax, start, end};
}

// 3. Maximum Product Subarray
public int maxProduct(int[] nums) {
    int maxProd = nums[0], minProd = nums[0], result = nums[0];
    for (int i = 1; i < nums.length; i++) {
        if (nums[i] < 0) { // Swap when negative
            int temp = maxProd;
            maxProd = minProd;
            minProd = temp;
        }
        maxProd = Math.max(nums[i], maxProd * nums[i]);
        minProd = Math.min(nums[i], minProd * nums[i]);
        result = Math.max(result, maxProd);
    }
    return result;
}

// 4. Maximum Circular Subarray Sum
public int maxCircularSubarray(int[] nums) {
    int totalSum = 0;
    int maxSum = nums[0], curMax = 0;
    int minSum = nums[0], curMin = 0;
    for (int num : nums) {
        curMax = Math.max(num, curMax + num);
        maxSum = Math.max(maxSum, curMax);
        curMin = Math.min(num, curMin + num);
        minSum = Math.min(minSum, curMin);
        totalSum += num;
    }
    // If all negative, maxSum is the answer
    return maxSum < 0 ? maxSum : Math.max(maxSum, totalSum - minSum);
}', 6 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'dsa' AND s.slug = 'arrays-strings';
