INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'files', 'Files & Directories Overview', 'Navigate and manage the Linux file system like a pro', 'The Linux file system is a hierarchical structure starting from the root directory (/). Everything in Linux is a file - including devices, processes, and network connections.

Key directories:
- **/home**: User home directories
- **/etc**: Configuration files
- **/var**: Variable data (logs, caches)
- **/usr**: User programs and utilities', 'Understanding the file system is crucial for server administration, DevOps, and debugging production issues.', '["Using rm -rf without caution","Incorrect file permissions","Not understanding relative vs absolute paths","Ignoring hidden files (dotfiles)"]', '["Always use tab completion","Use ls -la to see all file details","Backup before modifying system files","Understand permission implications"]', 'Basic Linux skills are expected for any backend/DevOps role. Know your way around the terminal.', NULL, 'bash', '# Essential file system commands
ls -la          # List all files with details
cd /path/to/dir # Change directory
pwd             # Print working directory
mkdir -p dir    # Create directory (with parents)
cp -r src dest  # Copy recursively
mv old new      # Move/rename
rm -rf dir      # Remove directory (careful!)
find . -name "*.log" # Find files by pattern
chmod 755 file  # Change permissions
chown user:group file # Change ownership', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'linux' AND s.slug = 'filesystem';
