INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'arrays', 'Arrays', 'Master fundamental array and string manipulation techniques used in coding interviews', 'Arrays are contiguous blocks of memory that store elements of the same type. They provide O(1) random access but O(n) insertion/deletion. Strings in most languages are immutable arrays of characters.

Key concepts include:
- **Indexing**: Access elements in constant time using indices
- **Traversal**: Linear scan through all elements
- **Sliding Window**: Maintain a window of elements for subarray problems
- **Two Pointers**: Use two indices to solve problems efficiently', 'Arrays are used everywhere - from storing user data in databases to managing pixel data in images. Strings power everything from search engines to messaging apps.', '["Off-by-one errors in loop boundaries","Not handling empty arrays/strings","Modifying array while iterating","Forgetting string immutability in Java/Python"]', '["Always validate input bounds","Use StringBuilder for string concatenation in loops","Consider in-place modifications to save space","Pre-calculate prefix sums for range queries"]', 'Arrays and strings appear in 70%+ of coding interviews. Master sliding window, two pointers, and prefix sum patterns.', '15 min', 'java', '// Two Sum - O(n) solution using HashMap
public int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> map = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement)) {
            return new int[] { map.get(complement), i };
        }
        map.put(nums[i], i);
    }
    return new int[] {};
}', 4 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'java' AND s.slug = 'core-java';
