INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'images', 'Docker Images Overview', 'Build efficient container images with Dockerfile best practices', 'Docker images are read-only templates used to create containers. They consist of layers, where each instruction in a Dockerfile creates a new layer.

Key concepts:
- **Base image**: Starting point (FROM instruction)
- **Layers**: Each instruction creates a cacheable layer
- **Build context**: Files available during build
- **Multi-stage builds**: Optimize final image size', 'Container images are the deployment unit in modern cloud-native applications. Efficient images reduce costs and improve deployment speed.', '["Using large base images","Not leveraging build cache","Including unnecessary files","Running as root user"]', '["Use official slim/alpine base images","Order instructions by change frequency","Use multi-stage builds","Scan images for vulnerabilities"]', 'Docker is essential for DevOps roles. Understand image optimization and Dockerfile best practices.', NULL, 'yaml', '# Optimized multi-stage Dockerfile
FROM node:18-alpine AS builder
WORKDIR /app
COPY package*.json ./
RUN npm ci --only=production
COPY . .
RUN npm run build

FROM node:18-alpine AS runner
WORKDIR /app
RUN addgroup -g 1001 -S nodejs
RUN adduser -S nextjs -u 1001
COPY --from=builder --chown=nextjs:nodejs /app/.next ./.next
COPY --from=builder /app/node_modules ./node_modules
COPY --from=builder /app/package.json ./package.json
USER nextjs
EXPOSE 3000
CMD ["npm", "start"]', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'docker' AND s.slug = 'images';
