INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'llm-fundamentals', 'LLM Fundamentals Overview', 'Understand how large language models work under the hood', 'Large Language Models (LLMs) are neural networks trained on massive text datasets to understand and generate human-like text.

Key concepts:
- **Transformers**: The architecture behind modern LLMs using self-attention
- **Tokenization**: Breaking text into subword units for processing
- **Attention Mechanism**: Allows models to focus on relevant parts of input
- **Context Window**: Maximum tokens a model can process at once
- **Temperature**: Controls randomness in output generation', 'LLMs power chatbots, code assistants, content generation, translation, and countless AI applications transforming every industry.', '["Not understanding token limits","Ignoring model hallucinations","Using wrong model for the task","Not considering latency and costs"]', '["Choose models based on task requirements","Implement proper error handling","Use streaming for better UX","Monitor token usage and costs"]', 'LLM knowledge is essential for AI/ML roles. Understand transformer architecture, tokenization, and model capabilities.', NULL, 'javascript', '// Basic LLM API call with OpenAI SDK
import OpenAI from ''openai'';

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

async function chat(userMessage: string) {
  const response = await openai.chat.completions.create({
    model: "gpt-4",
    messages: [
      { role: "system", content: "You are a helpful assistant." },
      { role: "user", content: userMessage }
    ],
    temperature: 0.7,
    max_tokens: 1000,
  });
  
  return response.choices[0].message.content;
}

// Streaming response for better UX
async function streamChat(userMessage: string) {
  const stream = await openai.chat.completions.create({
    model: "gpt-4",
    messages: [{ role: "user", content: userMessage }],
    stream: true,
  });
  
  for await (const chunk of stream) {
    process.stdout.write(chunk.choices[0]?.delta?.content || "");
  }
}', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'ai' AND s.slug = 'llm-fundamentals';
