INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'prompt-engineering', 'Prompt Engineering Overview', 'Master the art of crafting effective prompts for LLMs', 'Prompt engineering is the practice of designing inputs that guide LLMs to produce desired outputs.

Key techniques:
- **Zero-shot**: Direct instructions without examples
- **Few-shot**: Providing examples to guide the model
- **Chain of Thought**: Breaking down reasoning step-by-step
- **System Prompts**: Setting context and behavior rules
- **Prompt Patterns**: Reusable templates for common tasks', 'Effective prompts can improve accuracy by 50%+, reduce costs, and enable complex reasoning in production AI systems.', '["Vague or ambiguous instructions","Not providing enough context","Overloading with too many instructions","Ignoring output format specification"]', '["Be specific and explicit","Use structured output formats (JSON)","Iterate and test prompts systematically","Version control your prompts"]', 'Prompt engineering is crucial for building production AI applications. Know techniques like CoT, few-shot, and structured outputs.', NULL, 'javascript', '// Chain of Thought prompting for complex reasoning
const systemPrompt = `You are an expert problem solver.
When given a problem, think through it step-by-step.
Format your response as:
1. Understanding: Restate the problem
2. Approach: Outline your solution strategy  
3. Steps: Work through each step
4. Answer: Provide the final answer`;

// Few-shot prompting with examples
const fewShotPrompt = `
Classify the sentiment of customer reviews.

Review: "This product is amazing! Best purchase ever."
Sentiment: Positive

Review: "Terrible quality, broke after one day."
Sentiment: Negative

Review: "It''s okay, nothing special but works fine."
Sentiment: Neutral

Review: "${userReview}"
Sentiment:`;

// Structured JSON output
const jsonPrompt = `Extract the following information as JSON:
{
  "name": "extracted name",
  "email": "extracted email", 
  "intent": "one of: inquiry, complaint, purchase"
}

Input: ${userInput}`;', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'ai' AND s.slug = 'prompt-engineering';
