INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'rag', 'RAG (Retrieval-Augmented Generation) Overview', 'Build AI applications that leverage external knowledge', 'RAG combines the power of LLMs with external knowledge retrieval to provide accurate, up-to-date, and verifiable responses.

Key components:
- **Vector Database**: Stores document embeddings for similarity search
- **Embeddings**: Dense vector representations of text
- **Chunking**: Breaking documents into retrievable pieces
- **Retrieval**: Finding relevant context for queries
- **Generation**: Using retrieved context to generate responses', 'RAG powers enterprise chatbots, documentation assistants, and any AI that needs access to private or current data beyond training.', '["Poor chunking strategies","Not considering retrieval quality","Ignoring context window limits","Missing hybrid search approaches"]', '["Use semantic chunking over fixed-size","Implement re-ranking for better relevance","Combine vector and keyword search","Evaluate retrieval quality metrics"]', 'RAG is the #1 pattern for production AI. Understand vector databases, embeddings, chunking, and retrieval optimization.', NULL, 'javascript', '// RAG implementation with vector database
import { OpenAIEmbeddings } from "@langchain/openai";
import { Pinecone } from "@pinecone-database/pinecone";

// 1. Create embeddings for documents
async function indexDocuments(documents: string[]) {
  const embeddings = new OpenAIEmbeddings();
  const pinecone = new Pinecone();
  const index = pinecone.index("knowledge-base");
  
  for (const doc of documents) {
    const vector = await embeddings.embedQuery(doc);
    await index.upsert([{
      id: generateId(),
      values: vector,
      metadata: { text: doc }
    }]);
  }
}

// 2. Retrieve relevant context
async function retrieve(query: string, topK = 5) {
  const embeddings = new OpenAIEmbeddings();
  const queryVector = await embeddings.embedQuery(query);
  
  const results = await index.query({
    vector: queryVector,
    topK,
    includeMetadata: true
  });
  
  return results.matches.map(m => m.metadata.text);
}

// 3. Generate with context
async function ragChat(query: string) {
  const context = await retrieve(query);
  
  return openai.chat.completions.create({
    model: "gpt-4",
    messages: [
      { role: "system", content: `Use this context: ${context.join("\n")}` },
      { role: "user", content: query }
    ]
  });
}', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'ai' AND s.slug = 'rag';
