INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'ai-agents', 'AI Agents Overview', 'Build autonomous AI agents that can reason, plan, and take actions', 'AI Agents are systems that use LLMs to reason about tasks, make plans, and execute actions using tools.

Key patterns:
- **ReAct**: Reasoning and Acting in an interleaved manner
- **Tool Use**: Giving LLMs access to external functions
- **Planning**: Breaking complex tasks into subtasks
- **Memory**: Short-term and long-term information storage
- **Reflection**: Self-evaluation and course correction', 'AI agents power autonomous customer support, coding assistants, research tools, and complex workflow automation.', '["No guardrails on agent actions","Infinite loops in reasoning","Poor error handling","Not validating tool outputs"]', '["Implement action limits and timeouts","Use structured tool definitions","Add human-in-the-loop for critical actions","Log all agent decisions for debugging"]', 'Agent architectures are hot topics. Understand ReAct, tool use, and production considerations for autonomous systems.', NULL, 'javascript', '// AI Agent with tool use
const tools = [
  {
    type: "function",
    function: {
      name: "search_web",
      description: "Search the web for current information",
      parameters: {
        type: "object",
        properties: {
          query: { type: "string", description: "Search query" }
        },
        required: ["query"]
      }
    }
  },
  {
    type: "function", 
    function: {
      name: "send_email",
      description: "Send an email to a recipient",
      parameters: {
        type: "object",
        properties: {
          to: { type: "string" },
          subject: { type: "string" },
          body: { type: "string" }
        },
        required: ["to", "subject", "body"]
      }
    }
  }
];

async function runAgent(task: string) {
  const messages = [{ role: "user", content: task }];
  
  while (true) {
    const response = await openai.chat.completions.create({
      model: "gpt-4",
      messages,
      tools,
      tool_choice: "auto"
    });
    
    const message = response.choices[0].message;
    messages.push(message);
    
    if (!message.tool_calls) break; // Agent is done
    
    // Execute tools and add results
    for (const call of message.tool_calls) {
      const result = await executeTool(call);
      messages.push({
        role: "tool",
        tool_call_id: call.id,
        content: JSON.stringify(result)
      });
    }
  }
  
  return messages[messages.length - 1].content;
}', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'ai' AND s.slug = 'agents';
