INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'mcp', 'Model Context Protocol Overview', 'Connect AI models to external tools, data, and services', 'Model Context Protocol (MCP) is an open standard for connecting AI models to external data sources and tools in a secure, standardized way.

Key concepts:
- **MCP Servers**: Expose tools and resources to AI models
- **MCP Clients**: Connect to servers and use their capabilities
- **Tools**: Functions the model can call
- **Resources**: Data sources the model can access
- **Prompts**: Predefined prompt templates', 'MCP enables AI assistants to connect to databases, APIs, file systems, and enterprise tools securely and efficiently.', '["Exposing sensitive operations without auth","Not validating tool inputs","Poor error messages for the model","Ignoring rate limiting"]', '["Implement proper authentication","Use descriptive tool schemas","Provide helpful error messages","Test tool integrations thoroughly"]', 'MCP is emerging as the standard for AI integrations. Understand the architecture and how to build MCP servers.', NULL, 'javascript', '// MCP Server implementation
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";

const server = new Server(
  { name: "database-mcp", version: "1.0.0" },
  { capabilities: { tools: {} } }
);

// Define tools
server.setRequestHandler("tools/list", async () => ({
  tools: [
    {
      name: "query_database",
      description: "Execute a read-only SQL query",
      inputSchema: {
        type: "object",
        properties: {
          query: { type: "string", description: "SQL SELECT query" }
        },
        required: ["query"]
      }
    },
    {
      name: "get_schema",
      description: "Get the database schema",
      inputSchema: { type: "object", properties: {} }
    }
  ]
}));

// Handle tool calls
server.setRequestHandler("tools/call", async (request) => {
  const { name, arguments: args } = request.params;
  
  switch (name) {
    case "query_database":
      // Validate it''s a SELECT query (security!)
      if (!args.query.trim().toUpperCase().startsWith("SELECT")) {
        throw new Error("Only SELECT queries allowed");
      }
      const results = await db.query(args.query);
      return { content: [{ type: "text", text: JSON.stringify(results) }] };
      
    case "get_schema":
      const schema = await db.getSchema();
      return { content: [{ type: "text", text: schema }] };
  }
});

// Start server
const transport = new StdioServerTransport();
await server.connect(transport);', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'ai' AND s.slug = 'mcp';
