INSERT INTO lessons (section_id, slug, title, summary, concept, real_world, common_mistakes, best_practices, interview_relevance, duration, code_language, code_example, position) SELECT s.id, 'production-ai', 'Production AI Systems Overview', 'Deploy, monitor, and scale AI applications in production', 'Building production AI requires careful attention to reliability, observability, evaluation, and cost management.

Key areas:
- **Observability**: Tracing, logging, and monitoring AI calls
- **Evaluation**: Measuring quality with automated evals
- **Fine-tuning**: Customizing models for specific tasks
- **Cost Optimization**: Reducing API costs at scale
- **Reliability**: Fallbacks, retries, and error handling', 'Production AI systems at scale handle millions of requests daily, requiring robust infrastructure and careful cost management.', '["No observability on AI calls","Missing automated evaluations","Ignoring cost until it''s too late","No fallback strategies"]', '["Implement tracing from day one","Build automated eval suites","Use caching aggressively","Set up cost alerts and limits"]', 'Production ML/AI experience is highly valued. Know observability tools, evaluation frameworks, and cost optimization strategies.', NULL, 'javascript', '// Production AI with observability and fallbacks
import { trace } from "@opentelemetry/api";

async function productionChat(
  messages: Message[],
  options: { fallbackModel?: string } = {}
) {
  const span = trace.getTracer("ai").startSpan("chat_completion");
  
  try {
    span.setAttributes({
      "ai.model": "gpt-4",
      "ai.messages.count": messages.length,
      "ai.tokens.estimate": estimateTokens(messages)
    });
    
    // Check cache first
    const cacheKey = hashMessages(messages);
    const cached = await cache.get(cacheKey);
    if (cached) {
      span.setAttributes({ "ai.cache": "hit" });
      return cached;
    }
    
    // Primary model with timeout
    const response = await Promise.race([
      openai.chat.completions.create({
        model: "gpt-4",
        messages
      }),
      timeout(30000)
    ]);
    
    // Log metrics
    const usage = response.usage;
    span.setAttributes({
      "ai.tokens.prompt": usage.prompt_tokens,
      "ai.tokens.completion": usage.completion_tokens,
      "ai.cost": calculateCost(usage)
    });
    
    // Cache successful responses
    await cache.set(cacheKey, response, { ttl: 3600 });
    
    return response;
    
  } catch (error) {
    span.recordException(error);
    
    // Fallback to cheaper/faster model
    if (options.fallbackModel) {
      return openai.chat.completions.create({
        model: options.fallbackModel,
        messages
      });
    }
    throw error;
    
  } finally {
    span.end();
  }
}', 0 FROM sections s JOIN tracks t ON t.id = s.track_id WHERE t.slug = 'ai' AND s.slug = 'production';
