INSERT INTO problems (slug, track_id, title, difficulty, category, concept, description, examples, constraints, hints, solution, language, starter_code) SELECT 'two-sum', id, 'Two Sum', 'easy', 'Arrays & Strings', 'Hash Tables', 'Given an array of integers `nums` and an integer `target`, return indices of the two numbers such that they add up to `target`.

You may assume that each input would have **exactly one solution**, and you may not use the same element twice.

You can return the answer in any order.', '[{"input":"nums = [2,7,11,15], target = 9","output":"[0,1]","explanation":"Because nums[0] + nums[1] == 9, we return [0, 1]."},{"input":"nums = [3,2,4], target = 6","output":"[1,2]","explanation":""},{"input":"nums = [3,3], target = 6","output":"[0,1]","explanation":""}]', '["2 <= nums.length <= 10^4","-10^9 <= nums[i] <= 10^9","-10^9 <= target <= 10^9","Only one valid answer exists."]', '["A brute force approach would check every pair of numbers, but can we do better?","Think about how you can use a hash map to store values you''ve seen.","For each number, check if (target - number) exists in the hash map."]', 'class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> map = new HashMap<>();
        
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (map.containsKey(complement)) {
                return new int[] { map.get(complement), i };
            }
            map.put(nums[i], i);
        }
        
        return new int[] {};
    }
}', 'java', '' FROM tracks WHERE slug = 'dsa';
